look.customCSS:
/* ───── 哥特蕾丝 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/44px 44px,radial-gradient(circle at 50% 30%,#2A1822,#1D1219 70%) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：深色；底下挂一条酒红糖浆帘子往下滴 */
[data-wk="chathead"]{background:#160D13 !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;overflow:visible !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:63px !important;background:url("data:image/svg+xml;base64,") 0 0/216px 63px repeat-x !important;pointer-events:none !important;z-index:5 !important}
[data-wk="offline"] [data-wk="chathead"]::after{height:34px !important;background-size:216px 63px !important;background-position:0 0 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#F3E9EE !important}
[data-wk="headname"] [data-wk="headink"]{font-family:Georgia,"Songti SC",serif !important;letter-spacing:.12em !important}
[data-wk="chat"] [data-wk="headname"] [data-wk="headink"]::after{content:"my dearest" !important;font:italic 13px/1 Georgia,serif !important;color:#E68CA9 !important;margin-left:10px !important;letter-spacing:.04em !important;white-space:nowrap !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#9C8790 !important}
[data-wk="chatback"] svg{stroke:#F3E9EE !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important;flex-shrink:0 !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{width:46px !important;min-width:46px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:6px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：尖拱窗——白线框，顶上一颗小星 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"]{border-radius:50% 50% 3px 3px / 32% 32% 3px 3px !important;box-shadow:0 0 0 1.6px #F3E9EE,0 0 0 4px #1D1219,0 0 0 5.4px rgba(243,233,238,.5) !important;position:relative !important;overflow:visible !important}
button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="chathead"] [data-wk="avatar"] *{border-radius:50% 50% 3px 3px / 32% 32% 3px 3px !important}
[data-wk="msg"] [data-wk="avatar"]::before,[data-wk="cardrow"] [data-wk="avatar"]::before{content:"" !important;position:absolute !important;left:calc(50% - 6px) !important;top:-17px !important;width:12px !important;height:12px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTEwIDAgTDEyIDggTDIwIDEwIEwxMiAxMiBMMTAgMjAgTDggMTIgTDAgMTAgTDggOFonIGZpbGw9JyNGM0U5RUUnLz48L3N2Zz4=") center/contain no-repeat !important;z-index:2 !important}
[data-first="0"] [data-wk="avatar"]::before{content:none !important}
[data-wk="chathead"] [data-wk="headme"] *,[data-wk="chathead"] [data-wk="avatar"] *,[data-wk="chathead"] img,[data-wk="chathead"] button > span:first-child,[data-wk="chathead"] button > span:first-child *{border-radius:50% 50% 3px 3px / 32% 32% 3px 3px !important;overflow:hidden !important}
/* 顶栏双头像：两扇拱窗并排，中间一颗蝙蝠翅膀小心 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-4px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:34px !important;height:38px !important;min-width:34px !important;flex-shrink:0 !important;overflow:hidden !important}
img[data-wk="avatar"]{overflow:hidden !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-17px !important;bottom:-6px !important;width:30px !important;height:14px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}

/* 拱窗要瘦高，像参考里的鸟笼——宽 38 高 50，照片铺满 */
[data-wk="msg"] button[data-wk="avatar"],[data-wk="msg"] span[data-wk="avatar"],[data-wk="cardrow"] button[data-wk="avatar"],[data-wk="cardrow"] span[data-wk="avatar"]{width:38px !important;min-width:38px !important;height:50px !important}
[data-wk="msg"] [data-wk="avatar"] img,[data-wk="cardrow"] [data-wk="avatar"] img,[data-wk="msg"] img[data-wk="avatar"],[data-wk="cardrow"] img[data-wk="avatar"]{width:100% !important;height:100% !important;object-fit:cover !important}
[data-wk="msg"] img[data-wk="avatar"],[data-wk="cardrow"] img[data-wk="avatar"]{width:38px !important;height:50px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:30px !important;min-width:30px !important;height:40px !important;object-fit:cover !important}

/* 气泡：方角白线；靠头像那一侧一条束腰交叉系带，每串第一条在系带顶上打一个蝴蝶结 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:1.6px solid #F3E9EE !important;border-radius:6px !important;box-shadow:3px 3px 0 rgba(0,0,0,.35) !important;color:#F3E9EE !important;font-family:Georgia,"Songti SC",serif !important;letter-spacing:.06em !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#8A2846 !important;padding:10px 34px 10px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#1A1016 !important;padding:10px 18px 10px 34px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;top:4px !important;bottom:4px !important;width:18px !important;height:auto !important;background:url("data:image/svg+xml;base64,") center top/18px 12px repeat-y !important;border:none !important;transform:none !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:6px !important;left:auto !important;border-left:1px solid rgba(243,233,238,.35) !important;padding-left:2px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:6px !important;right:auto !important;border-right:1px solid rgba(243,233,238,.35) !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"]::after,[data-wk="msg"]:not([data-first]) [data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;top:-9px !important;width:24px !important;height:18px !important;border:none !important;transform:none !important;z-index:2 !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after,[data-wk="msg"]:not([data-first]) [data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:3px !important;left:auto !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after,[data-wk="msg"]:not([data-first]) [data-wk="bubble"][data-kind="text"][data-me="0"]::after{left:3px !important;right:auto !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}

/* 时间：一块用两条链子吊着的小牌子，切角、里面一道虚线框（照参考），下面一颗粉星 */
[data-wk="time"]{position:relative !important;padding-top:44px !important;padding-bottom:18px !important}
[data-wk="time"] > span{position:relative !important;display:inline-block !important;background:#1A1016 !important;border:1.4px solid #F3E9EE !important;border-radius:3px !important;color:#F3E9EE !important;font-family:Georgia,serif !important;letter-spacing:.2em !important;font-size:12px !important;padding:7px 26px !important;outline:1px dashed rgba(243,233,238,.7) !important;outline-offset:-5px !important}
[data-wk="time"]::before{content:"" !important;position:absolute !important;left:calc(50% - 44px) !important;top:14px !important;width:88px !important;height:30px !important;border-left:2px dotted #F3E9EE !important;border-right:2px dotted #F3E9EE !important}
[data-wk="time"]::after{content:"" !important;position:absolute !important;left:calc(50% - 6px) !important;bottom:0 !important;width:12px !important;height:12px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTEwIDAgTDEyIDggTDIwIDEwIEwxMiAxMiBMMTAgMjAgTDggMTIgTDAgMTAgTDggOFonIGZpbGw9JyNFNjhDQTknLz48L3N2Zz4=") center/contain no-repeat !important}

/* 已读：一行小字，旁边一颗蝙蝠翅膀小心——他的实心红、我的空心 */
[data-wk="meta"]{color:#9C8790 !important;font-size:10.5px !important;letter-spacing:.15em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:28px !important;height:12px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#9C8790 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#1A1016 !important;border:1.6px solid #F3E9EE !important;border-radius:6px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#E68CA9 !important}

/* 动描：不进气泡——一段烛光下的手写信：两头各一朵小十字花，深梅半透明底，粉灰斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:block !important;background:rgba(138,40,70,.14) !important;border:none !important;border-top:1px solid rgba(230,140,169,.35) !important;border-bottom:1px solid rgba(230,140,169,.35) !important;border-radius:0 !important;box-shadow:none !important;color:#D9B8C6 !important;opacity:1 !important;font-family:Georgia,"Songti SC",serif !important;font-style:italic !important;font-size:13px !important;line-height:1.85 !important;padding:10px 20px !important;text-align:center !important}
[data-wk="narrink"]::before,[data-wk="narrink"]::after{content:"✠" !important;color:#E68CA9 !important;font-style:normal !important;margin:0 8px !important;opacity:.8 !important}
/* 系统提示：不带框，等宽小字，前面一颗小星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9C8790 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnotetext"]::before{content:"✦ " !important;color:#E68CA9 !important}

/* 底栏：顶上一排尖拱蕾丝花边；加号、回复是两扇小拱门，发送是一颗带蝙蝠翅膀的红心 */
[data-wk="composer"]{background:#160D13 !important;border-top:1.6px solid #F3E9EE !important;position:relative !important;overflow:visible !important;align-items:center !important;gap:8px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:100% !important;height:40px !important;background:url("data:image/svg+xml;base64,") 0 100%/34px 40px repeat-x !important;pointer-events:none !important}
[data-wk="chatinput"]{background:#1A1016 !important;border:1.6px solid #F3E9EE !important;border-radius:6px !important;color:#F3E9EE !important;padding-left:34px !important;background-image:url("data:image/svg+xml;base64,") !important;background-repeat:repeat-y !important;background-size:18px 12px !important;background-position:8px 50% !important}
[data-wk="chatinput"]::placeholder{color:#9C8790 !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:38px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:62px !important;min-width:62px !important;height:40px !important;border:none !important;border-radius:0 !important;box-shadow:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:34px !important;min-width:34px !important;height:38px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]{transform:none !important;rotate:none !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
/* ───── 哥特蕾丝 · 第二批：卡片（形状不动；深色底白线框，左边一条束腰系带，像一封封黑色请柬） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:#1A1016 !important;border:1.6px solid #F3E9EE !important;border-radius:6px !important;box-shadow:3px 3px 0 rgba(0,0,0,.35),inset 0 0 0 4px #1A1016,inset 0 0 0 5px rgba(243,233,238,.35) !important;color:#F3E9EE !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *,[data-wk="wxcard"] *{color:#F3E9EE !important;border-color:rgba(243,233,238,.2) !important}
/* 转账：一张黑请柬——金额粉色衬线大字；收下在右上按一枚红色火漆印 */
[data-wk="transfercard"]{padding-top:22px !important}
[data-wk="transfercard"]::before{content:"✠  INVITATION  ✠" !important;position:absolute !important;left:0 !important;right:0 !important;top:9px !important;text-align:center !important;font:italic 10px/1 Georgia,serif !important;letter-spacing:.25em !important;color:#E68CA9 !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#E68CA9 !important;font-family:Georgia,serif !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,transparent,#E68CA9,transparent) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(138,40,70,.25) !important;border-top:1px solid rgba(243,233,238,.25) !important}
[data-wk="transferbtn"]{border-radius:4px !important}
[data-wk="transferbtn"][data-part="take"]{background:#8A2846 !important;border:1.6px solid #F3E9EE !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid rgba(243,233,238,.4) !important}
[data-wk="transferseal"]{background:transparent !important;border:none !important;box-shadow:none !important;color:transparent !important;width:46px !important;height:46px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;font-size:0 !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-12deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{filter:grayscale(1) !important}
/* 红包：不是信封——酒红小匣子，左边一颗大蝠翼红心，四角四颗小星；领完褪成暗红 */
[data-wk="rpcard"]{background:#8A2846 !important;padding-left:64px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:6px !important;top:calc(50% - 18px) !important;width:56px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="rpcard"]::after{content:"" !important;position:absolute !important;right:8px !important;top:8px !important;width:10px !important;height:10px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTEwIDAgTDEyIDggTDIwIDEwIEwxMiAxMiBMMTAgMjAgTDggMTIgTDAgMTAgTDggOFonIGZpbGw9JyNGM0U5RUUnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="rpcard"] *{color:#F3E9EE !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{background:#4A1E2D !important;opacity:.7 !important}
[data-wk="rpenvelope"]{background:url("data:image/svg+xml;base64,") 0 0/44px 44px,#8A2846 !important;border:1.6px solid #F3E9EE !important;border-radius:10px !important;box-shadow:inset 0 0 0 5px #8A2846,inset 0 0 0 6px rgba(243,233,238,.5),0 10px 30px rgba(0,0,0,.5) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#F3E9EE !important}
[data-wk="rpenvelope"][data-stage="open"]{background:url("data:image/svg+xml;base64,") 0 0/44px 44px,#1A1016 !important}
[data-wk="rpopenbtn"]{background:#C8234D !important;border:1.6px solid #F3E9EE !important;box-shadow:0 0 0 4px #8A2846,0 0 0 5.4px rgba(243,233,238,.5) !important}
[data-wk="rpopenbtn"] *{color:#fff !important}
[data-wk="rpamount"]{color:#E68CA9 !important;font-family:Georgia,serif !important}
/* 照片：拱窗里一张画；语音：黑色小条，侧边一截系带 */
[data-wk="photocard"]{padding:10px 10px 12px !important}
[data-wk="photoface"]{border-radius:50% 50% 3px 3px / 26% 26% 3px 3px !important;background:#2A1822 !important;border:1.2px solid rgba(243,233,238,.5) !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#F3E9EE !important}
[data-wk="photoface"] svg{stroke:#E68CA9 !important}
[data-wk="voice"][data-me]{position:relative !important;background:#1A1016 !important;border:1.6px solid #F3E9EE !important;border-radius:6px !important;padding-left:34px !important;overflow:visible !important}
[data-wk="voice"][data-me="1"]{background:#8A2846 !important}
[data-wk="voice"][data-me]::before{content:"" !important;position:absolute !important;left:6px !important;top:4px !important;bottom:4px !important;width:18px !important;background:url("data:image/svg+xml;base64,") center top/18px 12px repeat-y !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#F3E9EE !important}
[data-wk="voicewave"] span{background:#E68CA9 !important}
/* 天气、位置、名片 */
[data-wk="wxcardsky"]{background:radial-gradient(circle at 80% 20%,rgba(200,35,77,.3),transparent 60%),transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,rgba(230,140,169,.25),transparent 70%) !important}
[data-wk="wxcardsky"] svg{stroke:#E68CA9 !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:transparent !important;border:1px solid rgba(243,233,238,.5) !important;border-radius:4px !important}
[data-wk="wxcardtemp"]{font-family:Georgia,serif !important}
[data-wk="wxcardsay"]{background:rgba(138,40,70,.2) !important;border-top:1px solid rgba(243,233,238,.25) !important}
[data-wk="geopin"]{background:#C8234D !important;border-radius:50% 50% 50% 0 !important;box-shadow:0 0 0 2px #F3E9EE !important}
[data-wk="geopinstem"]{background:#F3E9EE !important}
[data-wk="namecard"] img{border-radius:50% 50% 3px 3px / 32% 32% 3px 3px !important;box-shadow:0 0 0 1.6px #F3E9EE !important}
/* 拍一拍、通话结束：两颗小星夹着一行衬线小字 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:transparent !important;border:none !important;color:#F3E9EE !important;font-family:Georgia,"Songti SC",serif !important;padding:2px 22px !important;font-size:12px !important;letter-spacing:.1em !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTEwIDAgTDEyIDggTDIwIDEwIEwxMiAxMiBMMTAgMjAgTDggMTIgTDAgMTAgTDggOFonIGZpbGw9JyNFNjhDQTknLz48L3N2Zz4=") left center/10px 10px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTEwIDAgTDEyIDggTDIwIDEwIEwxMiAxMiBMMTAgMjAgTDggMTIgTDAgMTAgTDggOFonIGZpbGw9JyNFNjhDQTknLz48L3N2Zz4=") right center/10px 10px no-repeat !important}
[data-wk="note"][data-part="call"] svg{stroke:#E68CA9 !important}
[data-wk="note"][data-part="callsum"]{color:#9C8790 !important}
/* 线下小结 */
[data-wk="offlogtitle"]{font-family:Georgia,serif !important;font-style:italic !important;letter-spacing:.2em !important;color:#E68CA9 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#E68CA9 !important}
[data-wk="offlogtranscript"]{border-top:1px solid rgba(243,233,238,.25) !important}
/* 加号面板：一扇扇小拱门，黑和酒红交替 */
[data-wk="chatpanel"]{background:#160D13 !important;border-top:1.6px solid #F3E9EE !important}
[data-wk="chattoolicon"]{background:#1A1016 !important;border:1.6px solid #F3E9EE !important;border-radius:50% 50% 4px 4px / 36% 36% 4px 4px !important;box-shadow:none !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{background:#8A2846 !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#F3E9EE !important;color:#F3E9EE !important}
[data-wk="chattoollabel"]{color:#9C8790 !important}
/* 引用三处：左边一截系带 */
[data-wk="quotedraft"]{background:#160D13 !important;border-top:none !important}
[data-wk="quote"]{position:relative !important;background:#1A1016 !important;color:#F3E9EE !important;border:1px solid rgba(243,233,238,.4) !important;border-radius:4px !important;padding-left:30px !important;opacity:1 !important;background-image:url("data:image/svg+xml;base64,") !important;background-repeat:repeat-y !important;background-size:18px 12px !important;background-position:6px 50% !important}
[data-wk="quote"][data-me="1"]{background-color:#8A2846 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#E68CA9 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:1.5px solid #E68CA9 !important;padding-left:8px !important;opacity:.75 !important}
/* 线下：提示键、照片键也是小拱门 */
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"]{width:28px !important;height:32px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"] *{opacity:0 !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"]{width:30px !important;min-width:30px !important;height:34px !important;border:none !important;box-shadow:none !important;font-size:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"] *{opacity:0 !important}
